    # Filter and normalise meetings
    filtered = []
    for m in meetings:
        # Ensure m is indexable and has at least two items
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        # Only consider numeric comparable values; if they can't be compared, skip
        try:
            if start <= end:
                filtered.append((start, end))
