def solve(s):
    """Convert a Roman numeral to integer.
    Assumes s is a valid Roman numeral consisting of characters I,V,X,L,C,D,M.
    """
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
             'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s.upper()):
