def solve(coins, amount):
    """Return the minimum number of coins needed to make up ``amount`` using unlimited
    coins of the given denominations. If it is impossible, return -1.
    ``coins`` is a list of positive integers, ``amount`` is a non‑negative integer.
    """
    # Edge case: amount zero requires zero coins
    if amount == 0:
        return 0
    # Initialize DP array with a value larger than any possible answer
    max_val = amount + 1  # greater than any feasible number of coins
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
