def solve(n, b):
    """Write integer n in base b (2-36) using digits 0-9 then a-z,
    with a leading minus sign for negative n."""
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    sign = '-' if n < 0 else ''
    n = abs(n)
    out = []
    while n > 0:
        out.append(digits[n % b])
        n //= b
    return sign + ''.join(reversed(out))

