def solve(n, edges):
    """Return the minimum total weight from node 0 to node n-1 in an undirected graph.
    If node n-1 is unreachable, return -1. Uses Dijkstra's algorithm.
    """
    if n <= 0:
        return -1
    if n == 1:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        if a < 0 or a >= n or b < 0 or b >= n:
            continue  # ignore invalid nodes
        if w < 0:
            continue  # ignore non‑positive weight as per spec (positive weights only)
        adj[a].append((b, w))
        adj[b].append((a, w))
    import heapq
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]  # (dist, node)
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist[n-1] if dist[n-1] != INF else -1

